const CALENDARIO_AP=[["2027-01-24","V Corrida do Farmacêutico do Amapá","Amapá","A confirmar"],["2027-01-31","2ª Corrida do SINSGAAP","Amapá","A confirmar"],["2027-02-14","Treinão Fun Fest I","Amapá","A confirmar"],["2027-02-21","3ª Corrida da Embaixada do Flamengo no Amapá","Macapá","A confirmar"],["2027-03-28","Corrida da Polícia Federal","Amapá","A confirmar"],["2027-04-04","1ª Corrida do Autismo da Clínica Lupo","Amapá","A confirmar"],["2027-04-11","Corrida do Serralheiro","Amapá","A confirmar"],["2027-05-01","Treinão Fun Fest II","Amapá","A confirmar"],["2027-05-16","Treinão Hero Pulse","Amapá","A confirmar"],["2027-05-23","Corrida ADEPAP","Amapá","A confirmar"],["2027-05-30","1ª Corrida pela Fé","Amapá","A confirmar"],["2027-06-06","Corrida da Democracia","Amapá","A confirmar"],["2027-09-26","Mountain Do Selva Amazônica","Amapá","A confirmar"]].map(([data,nome,cidade,distancia])=>({data,nome,cidade,distancia}));
let calendarioAno=2027,calendarioBusca='';
function calendarioPesquisar(valor){calendarioBusca=valor;const area=document.getElementById('calendarioLista');if(area)area.innerHTML=calendarioLinhas()}
function calendarioLinhas(){const eventos=CALENDARIO_AP.filter(e=>Number(e.data.slice(0,4))===calendarioAno&&[e.nome,e.cidade,e.distancia].join(' ').toLowerCase().includes(calendarioBusca.toLowerCase()));return eventos.map(e=>{const dia=e.data.slice(8,10),mes=new Date(e.data+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.','');return '<article class="cal-event"><div class="cal-date"><strong>'+dia+'</strong><span>'+mes+'</span></div><div class="cal-info"><strong>'+esc(e.nome)+'</strong><span>📍 '+esc(e.cidade)+' • '+esc(e.distancia)+'</span></div><span class="cal-tag">'+(e.data<new Date().toISOString().slice(0,10)?'Realizada':'Programação')+'</span></article>'}).join('')||'<p>Nenhum evento encontrado para esta busca.</p>'}
function calendarioAmapa(){return `<div class="panel cal-panel"><div class="treino-section-head"><div><span class="treino-eyebrow">AGENDA DE PROVAS DO AMAPÁ</span><h3>📅 Calendário de corridas 2027</h3></div><span class="treino-live">Fonte externa • sujeito a alterações</span></div><p class="muted">Eventos divulgados em calendários públicos. Datas, inscrições, distâncias e municípios devem ser confirmados com os organizadores. A inclusão aqui não significa homologação para pontuar no ranking oficial.</p><label for="calBusca">Buscar por corrida, município ou distância</label><input id="calBusca" placeholder="Ex.: Macapá, 5 km, BOPE..." value="${esc(calendarioBusca)}" oninput="calendarioPesquisar(this.value)"><div id="calendarioLista" class="cal-list">${calendarioLinhas()}</div><p class="muted">Fontes: <a href="https://corridaderuaamapa.com.br/calendario-corridas-de-rua-amapa-2026/" target="_blank" rel="noopener noreferrer">Corrida de Rua Amapá</a> e <a href="https://corridas.run/ap/" target="_blank" rel="noopener noreferrer">Corridas.run</a>. Consulta inicial em 15/11/2026. Confira sempre os dados com o organizador.</p></div>`}
function provas(){return `${heading('Corridas no Amapá — 2027','Provas oficiais e resultados homologados')}<div class="panel"><h3>📅 Corridas homologadas</h3>${corridasOnline.map(c=>`<p><strong>${esc(c.nome)}</strong> • ${esc(c.cidade)} • ${esc(String(c.data).slice(0,10))} • ${esc(c.distancias)} • Organização: ${esc(c.organizador)}</p>`).join('')||'<p>Nenhuma corrida homologada ainda.</p>'}${corridasErro?`<p class="notice">${esc(corridasErro)}</p>`:''}<button class="btn secondary" onclick="carregarCorridas()">Atualizar corridas</button></div><div class="panel"><h3>Organizadores — sugerir corrida oficial</h3><p class="muted">Envie os dados da corrida para revisão. O evento somente será publicado após homologação administrativa.</p>${!onlineUser?'<p>Entre na conta em Meu perfil para sugerir uma corrida.</p>':`<form id="corridaForm" class="formgrid"><div class="full"><label>Nome oficial da corrida</label><input name="nome" required minlength="4" maxlength="120"></div><div><label>Município</label><select name="cidade">${['Macapá','Santana','Oiapoque','Porto Grande','Laranjal do Jari','Tartarugalzinho','Pedra Branca do Amapari','Mazagão','Calçoene','Amapá','Ferreira Gomes','Itaubal','Cutias','Pracuúba','Serra do Navio','Vitória do Jari'].map(c=>`<option>${c}</option>`).join('')}</select></div><div><label>Data da corrida</label><input type="date" name="data" min="2027-01-01" max="2027-12-31" required></div><div><label>Distâncias</label><input name="distancias" required placeholder="5 km" maxlength="120"></div><div><label>Organizador</label><input name="organizador" required minlength="3" maxlength="120"></div><button class="btn dark">${betaEditando?'Salvar correções e reenviar':'Enviar para homologação'}</button>${betaEditando?'<button class="btn secondary" type="button" onclick="cancelarEdicaoBeta()">Cancelar edição</button>':''}</form>`}</div>`}
function desafios(){let n=profile?submissions.filter(x=>x.status==='aprovado').length:0;return `${heading('Desafios e medalhas digitais','Acompanhe suas conquistas com resultados homologados')}<div class="cards">${challenges.map(c=>`<article class="card"><div class="medal">${c.ico}</div><h3>${c.nome}</h3><p>${c.desc}</p>${c.goal?`<div class="progress"><span style="width:${Math.min(100,n/c.goal*100)}%"></span></div><p>${Math.min(n,c.goal)} de ${c.goal} provas validadas</p>`:'<span class="pill">Validação por regra específica</span>'}</article>`).join('')}</div><div class="notice">Medalhas são conquistas demonstrativas. A emissão verificável e automática depende da implantação do backend e da homologação real das provas.</div>`}
function top5Online(){const atletas=(rankingOnline?.atletas||[]).filter(x=>x.dist==='5 km'&&!x.provisorio&&(x.sexo==='Masculino'||x.sexo==='Feminino'));const categorias=[['Masculino','Classificação geral masculina'],['Feminino','Classificação geral feminina']];return `<div class="panel"><h3>🏆 Top 5 premiável — classificação geral 5 km (2027)</h3><p class="muted">A premiação anual contempla exclusivamente a classificação geral masculina e a classificação geral feminina, do 1º ao 5º lugar de cada uma. Faixa etária, município, Elite/Amador e PcD permanecem como classificações com certificação digital, sem premiação física própria. Apenas atletas aptos à classificação definitiva aparecem abaixo.</p>${categorias.map(([sexo,titulo])=>{const grupo=atletas.filter(x=>x.sexo===sexo).sort((a,b)=>b.pontos-a.pontos||b.vitorias-a.vitorias||b.segundos-a.segundos||b.terceiros-a.terceiros||a.melhor_tempo-b.melhor_tempo).slice(0,5);return `<h4>${titulo}</h4><div class="tablewrap"><table><thead><tr><th>Posição</th><th>Atleta</th><th>Município</th><th>Pontos</th><th>Provas</th></tr></thead><tbody>${grupo.map((x,i)=>`<tr><td>${i+1}º</td><td>${esc(x.nome)}</td><td>${esc(x.cidade)}</td><td><strong>${Number(x.pontos).toFixed(2).replace('.',',')}</strong></td><td>${x.provas}/${x.referencia}</td></tr>`).join('')||'<tr><td colspan="5">Ainda não há atletas aptos nesta classificação.</td></tr>'}</tbody></table></div>`}).join('')}</div>`}
function premiacao(){return rankingOficialPausado();return `${top5Online()}${heading('Melhores corredores do ano','Premiação anual exclusiva da classificação geral masculina e feminina • 5 km • a partir de 2027')}<section class="hero" style="margin-top:20px"><div><div class="eyebrow">Premiação anual • a partir de 2027</div><h1>Top 5 geral masculino e feminino.</h1><p>Serão reconhecidos os cinco primeiros colocados da classificação geral masculina e os cinco primeiros da classificação geral feminina nos 5 km, após a homologação final. As demais classificações, incluindo faixa etária, município e modalidade Elite/Amador, receberão certificação digital, mas não premiação física.</p><button class="btn" onclick="go('rankings')">Ver classificação geral →</button></div><div class="hero-art">🏆</div></section>${cards([['🥇','1º lugar','Reconhecimento de campeão geral masculino e feminino'],['🥈','2º lugar','Reconhecimento de vice-campeão geral'],['🥉','3º lugar','Reconhecimento do terceiro lugar geral'],['🏅','4º lugar','Reconhecimento do quarto lugar geral'],['🏅','5º lugar','Reconhecimento do quinto lugar geral'],['📣','Galeria dos Campeões','Divulgação após homologação definitiva']])}<div class="notice">Os tipos de premiação e as condições de entrega de 2027 dependem do regulamento complementar, da homologação final e da disponibilidade orçamentária.</div>`}
let onlineUser=null,onlineProfile=null,onlineResults=[],onlineQueue=[];async function onlineRequest(path,method='GET',body){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},credentials:'same-origin',body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.erro||'Falha na solicitação');return data}let authRefreshPromise=null,authUltimaVerificacao=0,authAtualizando=false;
async function onlineRefresh(){
 if(!window.onlineAuth)return;
 if(authRefreshPromise)return authRefreshPromise;
 authRefreshPromise=(async()=>{
  let usuario;
  try{usuario=await window.onlineAuth.getUser()}catch(e){console.warn('Não foi possível verificar a sessão. Mantendo o estado até nova tentativa:',e.message);return}
  const anterior=onlineUser?.id||null,atual=usuario?.id||null;
  onlineUser=usuario;
  if(!usuario){onlineProfile=null;onlineResults=[];onlineQueue=[];perfilTreinos=[];perfilTreinosErro=''}
  else{
   if(anterior!==atual){onlineProfile=null;onlineResults=[];onlineQueue=[];perfilTreinos=[]}
   try{
    onlineProfile=(await onlineRequest('/api/atleta')).atleta;
    if(!onlineProfile&&profile?.nome&&profile?.cidade&&profile?.sexo&&profile?.faixa){
     try{onlineProfile=(await onlineRequest('/api/atleta','POST',{...profile,classe:profile.classe||''})).atleta}catch(e){console.warn('Sincronização pendente:',e.message)}
    }
    onlineResults=(await onlineRequest('/api/resultados')).resultados;
    onlineQueue=usuario.roles?.includes('admin')?(await onlineRequest('/api/resultados?fila=1')).resultados:[];
   }catch(e){console.warn('Dados da conta temporariamente indisponíveis:',e.message)}
  }
  if(['perfil','admin','beta2026'].includes(state.page))render();
  if(state.page==='perfil'&&usuario)carregarPerfilTreinos();
  if(state.page==='admin'&&usuario?.roles?.includes('admin')){carregarCadastros();carregarAdminCorridas()}
 })();
 try{return await authRefreshPromise}finally{authRefreshPromise=null}
}
window.addEventListener('auth-ready',onlineRefresh);
if(window.onlineAuth?.ready)window.onlineAuth.ready.then(()=>onlineRefresh()).catch(e=>console.warn('Inicialização da sessão:',e.message));
async function revalidarSessao(){
 if(!window.onlineAuth||authAtualizando||document.visibilityState==='hidden'||navigator.onLine===false)return;
 if(Date.now()-authUltimaVerificacao<15000)return;
 authAtualizando=true;authUltimaVerificacao=Date.now();
 try{await onlineRefresh()}catch(e){console.warn('Revalidação da sessão:',e.message)}finally{authAtualizando=false}
}
window.addEventListener('focus',revalidarSessao);
window.addEventListener('online',()=>{authUltimaVerificacao=0;revalidarSessao()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')revalidarSessao()});

let corridasOnline=[],corridasErro='',adminCorridas=null;
async function carregarCorridas(){try{const data=await onlineRequest('/api/corridas');corridasOnline=data.corridas||[];corridasErro=''}catch(e){corridasErro=e.message}if(state.page==='provas')render()}
async function carregarAdminCorridas(){if(!onlineUser?.roles?.includes('admin'))return;try{adminCorridas=await onlineRequest('/api/admin/corridas')}catch(e){console.warn(e.message)}if(state.page==='admin')render()}
async function analisarCorrida(id,status){if(!onlineUser?.roles?.includes('admin'))return;try{await onlineRequest('/api/admin/corridas','PATCH',{id,status});await carregarAdminCorridas();await carregarCorridas()}catch(e){alert(e.message)}}
function painelCorridasAdmin(){if(!onlineUser?.roles?.includes('admin'))return '';return `<div class="panel"><h3>📅 Corridas aguardando homologação</h3>${adminCorridas?.estatisticas?`<p>Atletas online: <strong>${adminCorridas.estatisticas.atletas}</strong> • Resultados pendentes: <strong>${adminCorridas.estatisticas.resultados_pendentes}</strong> • Resultados aprovados: <strong>${adminCorridas.estatisticas.resultados_aprovados}</strong> • Corridas aprovadas: <strong>${adminCorridas.estatisticas.corridas_aprovadas}</strong></p>`:''}${adminCorridas?.corridas?.map(c=>`<p><strong>${esc(c.nome)}</strong> • ${esc(c.cidade)} • ${esc(String(c.data).slice(0,10))} <button class="btn secondary" onclick="analisarCorrida(${Number(c.id)},'aprovada')">Aprovar</button> <button class="btn secondary" onclick="analisarCorrida(${Number(c.id)},'rejeitada')">Rejeitar</button></p>`).join('')||'<p>Nenhuma corrida pendente ou consulta ainda não realizada.</p>'}<button class="btn secondary" onclick="carregarAdminCorridas()">Atualizar indicadores</button></div>`}
function passaporte(){const validos=onlineResults.filter(r=>r.status==='aprovado'),dist=[...new Set(validos.map(r=>r.dist))];const recordes=dist.map(d=>{const x=validos.filter(r=>r.dist===d).sort((a,b)=>Number(a.tempo_segundos)-Number(b.tempo_segundos))[0];return x?`${esc(d)}: ${time(Number(x.tempo_segundos))}`:''}).filter(Boolean);return `<div class="panel"><h3>🌎 Passaporte Digital do Corredor — 2027</h3><p class="muted">Seu histórico pessoal de corridas oficiais homologadas, medalhas e recordes.</p>${onlineUser?`<p><strong>${validos.length}</strong> corridas homologadas • <strong>${validos.length}</strong> medalhas de participação • <strong>${dist.length}</strong> distâncias</p><p><strong>Recordes pessoais:</strong> ${recordes.join(' • ')||'Aguardando resultados homologados'}</p><div class="tablewrap"><table><thead><tr><th>Corrida</th><th>Data</th><th>Distância</th><th>Tempo</th></tr></thead><tbody>${validos.map(r=>`<tr><td>${esc(r.prova)}</td><td>${esc(String(r.data||'').slice(0,10))}</td><td>${esc(r.dist)}</td><td>${time(Number(r.tempo_segundos))}</td></tr>`).join('')||'<tr><td colspan="4">Ainda não há corridas homologadas.</td></tr>'}</tbody></table></div>`:'<p>Entre na conta online para acessar seu passaporte.</p>'}</div>`}
function medalhasParticipacao(){const aprovados=onlineResults.filter(r=>r.status==='aprovado');return `<div class="panel"><h3>🏅 Medalhas digitais de participação</h3><p class="muted">Cada resultado de corrida oficial de 2027 homologado pela administração gera uma medalha digital de participação. Resultados pendentes ou rejeitados não geram medalhas. A medalha reconhece a conclusão da prova, não a colocação no ranking.</p>${!onlineUser?'<p>Entre na sua conta para visualizar suas medalhas.</p>':!aprovados.length?'<p>Nenhuma medalha digital disponível ainda. Elas aparecerão após a homologação dos resultados oficiais.</p>':aprovados.map(r=>`<div class="panel" style="margin:12px 0;padding:16px"><strong>🏅 Participação confirmada</strong><p>${esc(r.prova||'Corrida oficial')} • ${esc(r.dist||'')} • ${esc(r.data||'Temporada 2027')}</p><button class="btn secondary" type="button" onclick="baixarMedalha(${Number(r.id)})">Baixar medalha digital</button></div>`).join('')}</div>`}
function baixarMedalha(id){const r=onlineResults.find(x=>Number(x.id)===Number(id)&&x.status==='aprovado');if(!r){alert('Medalha indisponível: resultado ainda não homologado.');return}const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const nome=String(r.prova||'Corrida oficial').trim();const palavras=nome.split(/\s+/);const linhas=[''];for(const palavra of palavras){const j=linhas.length-1;const tentativa=(linhas[j]+' '+palavra).trim();if(tentativa.length>32&&linhas[j]&&linhas.length<3)linhas.push(palavra);else linhas[j]=tentativa}const nomeSvg=linhas.map((linha,i)=>`<tspan x="450" dy="${i?37:0}">${safe(linha)}</tspan>`).join('');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="900" viewBox="0 0 900 900"><rect width="900" height="900" fill="#f8fbf8"/><circle cx="450" cy="425" r="340" fill="#fff" stroke="#0c643c" stroke-width="32"/><circle cx="450" cy="425" r="300" fill="none" stroke="#e4b437" stroke-width="10"/><text x="450" y="260" text-anchor="middle" font-family="Arial" font-size="43" font-weight="bold" fill="#0c643c">RANKING AMAPÁ RUNNING</text><text x="450" y="430" text-anchor="middle" font-family="Arial" font-size="140">🏅</text><text x="450" y="520" text-anchor="middle" font-family="Arial" font-size="49" font-weight="bold" fill="#0c643c">PARTICIPAÇÃO</text><text x="450" y="590" text-anchor="middle" font-family="Arial" font-size="30" fill="#193e2c">RESULTADO HOMOLOGADO • 2027</text><text x="450" y="635" text-anchor="middle" font-family="Arial" font-size="26" fill="#193e2c">${nomeSvg}</text><text x="450" y="750" text-anchor="middle" font-family="Arial" font-size="25" fill="#193e2c">${safe(r.dist||'')}</text></svg>`;const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='medalha-'+nome.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)+'-'+Number(r.id)+'.svg';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let inscricaoAnual=null,inscricoesAdmin=[],inscricaoErro='',inscricaoCarregada=false;
async function carregarInscricaoAnual(){if(!onlineUser){inscricaoAnual=null;inscricaoCarregada=false;return}inscricaoCarregada=true;try{inscricaoAnual=(await onlineRequest('/api/inscricoes-anuais')).inscricao}catch(e){inscricaoErro=e.message}if(state.page==='perfil')render()}
async function enviarComprovanteAnual(){if(!onlineUser)return alert('Entre na conta primeiro.');const el=document.getElementById('comprovanteAnual');const file=el?.files?.[0];if(!file)return alert('Selecione o comprovante.');if(file.size>1048576)return alert('O arquivo deve ter até 1 MB.');if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))return alert('Use JPG, PNG, WebP ou PDF.');if(!confirm('Enviar comprovante para análise? O envio não confirma o pagamento.'))return;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file)});await onlineRequest('/api/inscricoes-anuais','POST',{comprovante:data});await carregarInscricaoAnual();alert('Comprovante enviado. Aguarde a conferência do administrador.')}catch(e){alert(e.message)}}
async function carregarInscricoesAdmin(){if(!onlineUser?.roles?.includes('admin'))return;try{inscricoesAdmin=(await onlineRequest('/api/inscricoes-anuais?admin=1')).inscricoes;render()}catch(e){alert(e.message)}}
async function verComprovanteAnual(id){try{const r=await onlineRequest('/api/inscricoes-anuais?comprovante_id='+encodeURIComponent(id));const a=document.createElement('a');a.href=r.comprovante;a.download='comprovante-inscricao-'+id+(r.comprovante.startsWith('data:application/pdf')?'.pdf':'.png');document.body.appendChild(a);a.click();a.remove()}catch(e){alert(e.message)}}
async function analisarInscricaoAnual(id,status){if(!confirm((status==='aprovado'?'Confirmar recebimento do Pix e aprovar':'Rejeitar')+' inscrição #'+id+'?'))return;try{await onlineRequest('/api/inscricoes-anuais','PATCH',{id,status});await carregarInscricoesAdmin()}catch(e){alert(e.message)}}
function painelInscricoesAdmin(){return `<div class="panel"><h3>💳 Inscrições anuais — 2027</h3><p class="muted">Aprovar somente após conferir o recebimento de R$ 30,00 na conta Pix. O comprovante enviado não garante o crédito.</p><button class="btn secondary" onclick="carregarInscricoesAdmin()">Atualizar inscrições</button>${inscricoesAdmin.map(x=>`<div class="card" style="margin-top:10px"><strong>#${Number(x.id)} — ${esc(x.email)}</strong><p>R$ 30,00 • ${esc(x.status)} • ${esc(String(x.criado_em||'').slice(0,10))}</p><button class="btn secondary" onclick="verComprovanteAnual(${Number(x.id)})">Ver comprovante</button> ${x.status==='pendente'?`<button class="btn" onclick="analisarInscricaoAnual(${Number(x.id)},'aprovado')">Confirmar recebimento e aprovar</button> <button class="btn secondary" onclick="analisarInscricaoAnual(${Number(x.id)},'rejeitado')">Rejeitar</button>`:''}</div>`).join('')}</div>`}
function painelPagamentoAnual(){return `<div class="panel"><h3>💳 Inscrição anual — 2027</h3><p><strong>Taxa única: R$ 30,00 por atleta.</strong></p><p>Chave Pix aleatória: <code id="chavePixAnual">a9151da0-c332-4ec2-8bbc-7387ca0d4eee</code></p><button class="btn secondary" onclick="navigator.clipboard.writeText(document.getElementById('chavePixAnual').textContent).then(()=>alert('Chave Pix copiada.')).catch(()=>alert('Selecione e copie a chave acima.'))">Copiar chave Pix</button><p class="muted">Confira o nome do destinatário no aplicativo do banco antes de pagar. Não faça novo pagamento se já tiver pago; aguarde a análise.</p>${!onlineUser?'<p>Entre na conta abaixo para enviar o comprovante.</p>':`<p><strong>Situação: ${esc(inscricaoAnual?.status||'Não enviada')}</strong></p>${inscricaoAnual?.status==='aprovado'?'<p>Inscrição aprovada para 2027.</p>':`<label>Comprovante do Pix (JPG, PNG, WebP ou PDF, até 1 MB)</label><input id="comprovanteAnual" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf,image/jpeg,image/png,image/webp,application/pdf"><button class="btn" type="button" onclick="enviarComprovanteAnual()">Enviar comprovante para análise</button>`}`}<p class="muted">O envio não confirma a inscrição. A ativação depende da verificação do recebimento pelo administrador.</p></div>`}
function onlinePanel(){return `<div class="panel"><h3>🌐 Cadastro e acesso dos servidores do IFAP</h3>${!onlineUser?`<p class="muted">Entre com e-mail e senha. Sua sessão será recuperada automaticamente neste dispositivo enquanto estiver válida. Você só precisará entrar novamente se sair, a sessão expirar ou os dados do navegador forem apagados.</p><form id="onlineLogin"><label>E-mail</label><input type="email" name="email" required><label>Senha</label><input type="password" name="password" required minlength="8"><div class="actions"><button class="btn" name="action" value="login">Entrar</button><button class="btn secondary" name="action" value="signup">Criar conta</button></div></form>`:`<p>Conectado: <strong>${esc(onlineUser.email||'Atleta')}</strong></p><button class="btn secondary" onclick="onlineLogout()">Sair</button><h4>Perfil online</h4><p>${onlineProfile?'Perfil salvo: '+esc(onlineProfile.nome):'Salve seu pré-cadastro no formulário abaixo para criar seu perfil online.'}</p><button class="btn" onclick="onlineSaveProfile()">Salvar perfil no banco online</button><h4>Resultados enviados ao banco</h4><p>${onlineResults.length} resultado(s) enviado(s). A aprovação depende da equipe de homologação.</p>${onlineResults.map(r=>`<p>${esc(r.prova)} — ${esc(r.dist)} — ${esc(r.status)}</p>`).join('')}`}</div>`}
async function onlineLogout(){try{await window.onlineAuth.logout();onlineUser=null;inscricaoAnual=null;inscricaoCarregada=false;onlineProfile=null;onlineResults=[];onlineQueue=[];perfilTreinos=[];perfilTreinosErro='';render()}catch(e){alert(e.message)}}async function onlineSaveProfile(){if(!onlineUser){alert('Entre na sua conta primeiro.');return}if(!profile){alert('Preencha e salve o pré-cadastro abaixo.');return}try{onlineProfile=(await onlineRequest('/api/atleta','POST',profile)).atleta;alert('Perfil salvo no banco online.');render()}catch(e){alert(e.message)}}async function onlineApprove(id,status){if(!confirm('Confirmar '+status+' do resultado '+id+'?'))return;try{await onlineRequest('/api/resultados','PATCH',{id,status});await onlineRefresh();alert('Decisão registrada na auditoria.')}catch(e){alert(e.message)}}
async function atualizarFotoPerfil(input){const file=input.files?.[0];if(!file)return;if(!onlineUser||!onlineProfile){alert('Entre na conta e salve seu perfil online antes de enviar a foto.');input.value='';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){alert('Escolha uma foto JPG, PNG ou WebP.');return}if(file.size>8*1024*1024){alert('A imagem original deve ter no máximo 8 MB.');return}try{const img=await createImageBitmap(file);const scale=Math.min(1,480/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close();let data=canvas.toDataURL('image/jpeg',0.75);if(data.length>190000)data=canvas.toDataURL('image/jpeg',0.5);if(data.length>190000)throw Error('Não foi possível reduzir a foto. Escolha uma imagem menor.');onlineProfile=(await onlineRequest('/api/atleta','POST',{...onlineProfile,foto_perfil:data})).atleta;alert('Foto de perfil salva na sua conta.');render()}catch(e){alert('Não foi possível salvar a foto: '+e.message)}}
async function removerFotoPerfil(){if(!onlineProfile||!onlineUser||!confirm('Remover a foto do seu perfil?'))return;try{onlineProfile=(await onlineRequest('/api/atleta','POST',{...onlineProfile,foto_perfil:''})).atleta;render()}catch(e){alert(e.message)}}
function fotoPerfil(){const foto=onlineProfile?.foto_perfil;return `<div class="panel profile-photo-panel"><h3>📷 Foto do perfil</h3><div class="profile-photo-row"><div class="profile-avatar">${foto?`<img src="${esc(foto)}" alt="Foto do atleta">`:'<span aria-hidden="true">🏃</span>'}</div><div><p class="muted">Escolha uma foto da galeria do celular ou do computador. A imagem será otimizada e salva na sua conta.</p>${onlineUser&&onlineProfile?`<label class="btn dark photo-upload" for="fotoPerfilInput">📷 ${foto?'Trocar foto':'Carregar foto'}</label><input id="fotoPerfilInput" type="file" accept="image/jpeg,image/png,image/webp" style="display:none" onchange="atualizarFotoPerfil(this)">${foto?'<button class="btn secondary" type="button" onclick="removerFotoPerfil()">Remover foto</button>':''}`:'<p>Entre na sua conta e salve seu cadastro para ativar o envio da foto.</p>'}</div></div></div>`}
let perfilTreinos=[],perfilTreinosErro='',perfilTreinosCarregando=false;
async function carregarPerfilTreinos(){if(!onlineUser){perfilTreinos=[];return}perfilTreinosCarregando=true;try{const r=await onlineRequest('/api/perfil/estatisticas');perfilTreinos=r.treinos||[];perfilTreinosErro=''}catch(e){perfilTreinosErro=e.message}finally{perfilTreinosCarregando=false}if(state.page==='perfil'||state.page==='treino')render()}
async function excluirResultadoIFAP(id){const x=perfilTreinos.find(t=>Number(t.id)===Number(id));if(!x||!onlineUser)return;if(!confirm('Excluir o resultado de '+(x.nome_corrida||'corrida oficial')+'? A pontuação e a medalha digital associadas serão removidas.'))return;try{await onlineRequest('/api/treinos?id='+encodeURIComponent(id),{method:'DELETE'});perfilTreinos=perfilTreinos.filter(t=>Number(t.id)!==Number(id));await Promise.all([carregarPerfilTreinos(),treinoCarregar()]);render();alert('Resultado excluído com sucesso.')}catch(e){alert('Não foi possível excluir: '+e.message)}}
function meusResultadosIFAP(){if(!onlineUser)return '';const corridas=perfilTreinos.filter(x=>x.origem==='corrida_oficial');return `<div class="panel"><h3>🗂️ Meus resultados cadastrados</h3><p class="muted">Você pode excluir resultados pendentes ou homologados. A exclusão retira os pontos do ranking e cancela a medalha digital.</p><div class="tablewrap"><table><thead><tr><th>Corrida</th><th>Data</th><th>Tempo</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${corridas.map(x=>`<tr><td>${esc(x.nome_corrida||'Corrida oficial')}</td><td>${esc(new Date(x.iniciado_em).toLocaleDateString('pt-BR'))}</td><td>${treinoDuracao(x.duracao_s)}</td><td>${x.homologado_em?'Homologado':'Aguardando homologação'}</td><td><button class="btn secondary" onclick="excluirResultadoIFAP(${Number(x.id)})">Excluir resultado</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhuma corrida cadastrada.</td></tr>'}</tbody></table></div></div>`}
function medalhasCorridasIFAP(){if(!onlineUser)return '';const corridas=perfilTreinos.filter(x=>x.origem==='corrida_oficial'&&Boolean(x.homologado_em));return `<section class="panel" id="galeria-medalhas-ifap"><h3>🏅 Galeria de medalhas — Corridas IFAP</h3><p class="muted">Cada corrida oficial de 5 km homologada rende uma medalha digital exibida aqui na sua galeria. Não é necessário baixar imagem.</p>${perfilTreinosCarregando?'<p class="muted">Carregando medalhas...</p>':''}${perfilTreinosErro?`<p class="muted">Não foi possível carregar as medalhas: ${esc(perfilTreinosErro)}</p>`:''}<div class="cards">${corridas.map(x=>`<article class="card" style="text-align:center;min-width:0"><div aria-label="Medalha digital conquistada" role="img" style="display:flex;flex-direction:column;align-items:center;margin:12px auto 20px"><div style="display:flex;gap:8px"><span style="width:24px;height:48px;background:#138657;transform:skew(15deg);border-radius:4px"></span><span style="width:24px;height:48px;background:#e6b84b;transform:skew(-15deg);border-radius:4px"></span></div><div style="width:116px;height:116px;border-radius:50%;border:9px double #b48b30;background:radial-gradient(circle at 30% 25%,#fff2ad,#e5b948 55%,#ac7825);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 14px #0003;margin-top:-8px"><span style="font-weight:900;font-size:30px;color:#63420d;text-shadow:0 1px #fff9">5 KM</span></div></div><strong style="display:block;overflow-wrap:anywhere">${esc(x.nome_corrida||'Corrida oficial de 5 km')}</strong><p>${esc(new Date(x.iniciado_em).toLocaleDateString('pt-BR'))} • ${treinoDuracao(x.duracao_s)}</p><p><strong>${Number(x.pontos).toFixed(2).replace('.',',')} pontos</strong></p><span class="pill">✓ Conquistada e homologada</span></article>`).join('')||(!perfilTreinosCarregando?'<p class="muted">Nenhuma medalha conquistada ainda. Sua primeira medalha aparecerá automaticamente após a homologação de uma corrida oficial de 5 km.</p>':'')}</div><button class="btn secondary" type="button" onclick="carregarPerfilTreinos()">Atualizar galeria</button></section>`}
function baixarMedalhaIFAP(id){const x=perfilTreinos.find(t=>Number(t.id)===Number(id)&&t.origem==='corrida_oficial'&&t.homologado_em);if(!x)return alert('Medalha disponível apenas após homologação.');const cv=document.createElement('canvas');cv.width=1080;cv.height=1080;const g=cv.getContext('2d');if(!g)return;const bg=g.createLinearGradient(0,0,1080,1080);bg.addColorStop(0,'#073c32');bg.addColorStop(1,'#0b181c');g.fillStyle=bg;g.fillRect(0,0,1080,1080);g.textAlign='center';const draw=(s,y,size,color)=>{g.fillStyle=color;g.font='bold '+size+'px sans-serif';while(g.measureText(s).width>950&&size>23){size-=2;g.font='bold '+size+'px sans-serif'}g.fillText(s,540,y)};draw('RANKING AMAPÁ RUNNING',105,45,'#f0d17c');draw('MEDALHA DIGITAL • 5 KM',185,48,'#f0d17c');g.font='210px serif';g.fillText('🏅',540,440);draw(String(onlineProfile?.nome||profile?.nome||'Servidor IFAP'),565,55,'#ffffff');draw(String(x.nome_corrida||'Corrida oficial'),660,50,'#f0d17c');draw(new Date(x.iniciado_em).toLocaleDateString('pt-BR')+' • '+treinoDuracao(x.duracao_s),740,42,'#ffffff');draw(Number(x.pontos).toFixed(2).replace('.',',')+' pontos',825,42,'#f0d17c');draw('RESULTADO OFICIAL HOMOLOGADO',955,35,'#ffffff');const a=document.createElement('a');a.download='medalha-ifap-'+Number(x.id)+'.png';a.href=cv.toDataURL('image/png');a.click()}
async function compartilharPerfilCorredor(){
 if(!onlineUser){alert('Entre na sua conta para compartilhar seu desempenho.');return}
 const treinos=perfilTreinos.map(t=>({km:Number(t.distancia_m)/1000,seg:Number(t.duracao_s),pts:Number(t.pontos),data:String(t.iniciado_em||'')})).filter(t=>t.km>0&&t.seg>0);
 const km=treinos.reduce((v,t)=>v+t.km,0),seg=treinos.reduce((v,t)=>v+t.seg,0),pontos=treinos.reduce((v,t)=>v+t.pts,0);
 const nome=onlineProfile?.nome||profile?.nome||'Corredor',cidade=onlineProfile?.cidade||profile?.cidade||'Amapá';
 const melhorDist=treinos.length?Math.max(...treinos.map(t=>t.km)):0,melhorRitmo=treinos.length?Math.min(...treinos.map(t=>t.seg/t.km)):0;
 const fmt=n=>Number(n).toFixed(2).replace('.',',');
 const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1600;
 const c=canvas.getContext('2d');if(!c){alert('Não foi possível criar a imagem neste dispositivo.');return}
 const gradient=c.createLinearGradient(0,0,1080,1600);gradient.addColorStop(0,'#082d42');gradient.addColorStop(.65,'#095765');gradient.addColorStop(1,'#062c3e');c.fillStyle=gradient;c.fillRect(0,0,1080,1600);
 const rounded=(x,y,w,h,r,fill)=>{c.fillStyle=fill;c.beginPath();c.roundRect(x,y,w,h,r);c.fill()};
 const write=(text,x,y,size=34,color='#fff',weight='600')=>{c.fillStyle=color;c.font=weight+' '+size+'px system-ui,Arial,sans-serif';c.fillText(String(text),x,y)};
 const fit=(text,x,y,max=820,size=58)=>{let n=size;c.font='800 '+n+'px system-ui,Arial,sans-serif';while(c.measureText(text).width>max&&n>26){n-=2;c.font='800 '+n+'px system-ui,Arial,sans-serif'}write(text,x,y,n)};
 write('RANKING AMAPÁ RUNNING',64,94,35,'#61e6c6','800');
 write('MEU DESEMPENHO',64,156,26,'#a4d8dc','700');
 c.fillStyle='#2cddad';c.fillRect(64,184,952,5);
 fit(nome,64,274,940,62);
 write(cidade+' • Perfil do corredor',64,324,28,'#bce4e7','500');
 const stat=(x,y,w,label,value)=>{rounded(x,y,w,165,22,'rgba(255,255,255,.10)');write(label,x+26,y+43,23,'#bde5e8','500');write(value,x+26,y+113,45,'#ffffff','800')};
 stat(64,370,455,'DISTÂNCIA TOTAL',fmt(km)+' km');
 stat(560,370,456,'TREINOS VÁLIDOS',String(treinos.length));
 stat(64,553,455,'TEMPO ACUMULADO',treinoDuracao(seg));
 stat(560,553,456,'PONTUAÇÃO',fmt(pontos)+' pts');
 stat(64,736,455,'RITMO MÉDIO',seg?treinoDuracao(Math.round(seg/km))+' /km':'—');
 stat(560,736,456,'VELOCIDADE MÉDIA',seg?fmt(km*3600/seg)+' km/h':'—');
 write('RECORDES PESSOAIS',64,966,30,'#61e6c6','800');
 rounded(64,991,952,130,20,'rgba(255,255,255,.10)');
 write('Maior distância',88,1034,25,'#bde5e8');write(fmt(melhorDist)+' km',88,1090,39);
 write('Melhor ritmo',570,1034,25,'#bde5e8');write(treinos.length?treinoDuracao(Math.round(melhorRitmo))+' /km':'—',570,1090,39);
 write('EVOLUÇÃO MENSAL',64,1181,30,'#61e6c6','800');
 const meses={};treinos.forEach(t=>{const m=t.data.slice(0,7);if(/^\\d{4}-\\d{2}$/.test(m))meses[m]=(meses[m]||0)+t.km});
 const ultimos=Object.entries(meses).sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),max=Math.max(1,...ultimos.map(x=>x[1]));
 if(!ultimos.length)write('Sem registros de evolução.',64,1252,28,'#bde5e8');
 ultimos.forEach(([mes,v],i)=>{const width=100,x=70+i*160,altura=100*v/max;rounded(x,1330-altura,width,altura,9,'#37d9b0');write(fmt(v),x,1368,22,'#fff');write(mes.slice(5)+'/'+mes.slice(2,4),x,1405,22,'#bde5e8')});
 write('MEDALHAS DE TREINO',64,1474,27,'#61e6c6','800');
 const conquistas=[treinos.length>=1?'Primeiros passos':null,treinos.length>=10?'Constância':null,km>=100?'100 km':null,km>=500?'Meio do Mundo':null,melhorDist>=21.1?'Longa distância':null].filter(Boolean);
 write(conquistas.length?conquistas.join('  •  '):'Nenhuma medalha conquistada ainda',64,1516,23,'#ffffff');
 write('Dados de treinos GPS online • '+new Date().toLocaleDateString('pt-BR'),64,1563,20,'#a4d8dc','500');
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob){alert('Não foi possível exportar a imagem.');return}
 const file=new File([blob],'ranking-amapa-desempenho.png',{type:'image/png'});
 if(navigator.canShare&&navigator.share&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:'Meu desempenho • Ranking Amapá Running',text:'Meu desempenho no Ranking Amapá Running'});return}catch(e){if(e.name==='AbortError')return}}
 const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=file.name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
function perfilEstatisticas(){
 const a=perfilTreinos.map(t=>({...t,km:Number(t.distancia_m)/1000,seg:Number(t.duracao_s),pts:Number(t.pontos)})).filter(t=>t.km>0&&t.seg>0);
 const soma=(f)=>a.reduce((v,t)=>v+f(t),0),km=soma(t=>t.km),seg=soma(t=>t.seg),pts=soma(t=>t.pts);
 const melhorKm=a.length?Math.max(...a.map(t=>t.km)):0;
 const melhorRitmo=a.length?Math.min(...a.map(t=>t.seg/t.km)):0;
 const velocidade=seg?km*3600/seg:0;
 const meses={};a.forEach(t=>{const m=String(t.iniciado_em).slice(0,7);meses[m]=(meses[m]||0)+t.km});
 const ultimos=Object.entries(meses).sort((x,y)=>x[0].localeCompare(y[0])).slice(-6);
 const maximo=Math.max(1,...ultimos.map(x=>x[1]));
 const medals=[
 {ico:'🥉',titulo:'Primeiros passos',desc:'Concluir o primeiro treino',ok:a.length>=1},
 {ico:'🥈',titulo:'Constância',desc:'Concluir 10 treinos',ok:a.length>=10},
 {ico:'🥇',titulo:'100 km acumulados',desc:'Alcançar 100 km de treinos',ok:km>=100},
 {ico:'🏅',titulo:'Meio do Mundo',desc:'Alcançar 500 km acumulados',ok:km>=500},
 {ico:'🏆',titulo:'Corredor de longa distância',desc:'Concluir um treino de 21,1 km',ok:melhorKm>=21.1}
 ];
 return `<div class="panel perfil-dashboard"><div class="treino-section-head"><div><span class="treino-eyebrow">MEU DESEMPENHO</span><h3>📊 Estatísticas do corredor</h3></div><div class="treino-actions"><button class="btn secondary" onclick="carregarPerfilTreinos()">↻ Atualizar dados</button><button class="btn dark" onclick="compartilharPerfilCorredor()">🖼️ Compartilhar imagem</button></div></div>${!onlineUser?'<p class="notice">Entre na sua conta para visualizar estatísticas e medalhas dos treinos registrados online.</p>':perfilTreinosErro?'<p class="notice">'+esc(perfilTreinosErro)+'</p>':''}<div class="perfil-stats"><div class="card"><small>Distância acumulada</small><strong>${km.toFixed(2).replace('.',',')} km</strong></div><div class="card"><small>Treinos válidos</small><strong>${a.length}</strong></div><div class="card"><small>Tempo total</small><strong>${treinoDuracao(seg)}</strong></div><div class="card"><small>Pontos acumulados</small><strong>${pts.toFixed(2).replace('.',',')}</strong></div><div class="card"><small>Velocidade média geral</small><strong>${velocidade.toFixed(2).replace('.',',')} km/h</strong></div><div class="card"><small>Ritmo médio geral</small><strong>${seg?treinoDuracao(Math.round(seg/km))+' /km':'—'}</strong></div></div><h4>🏆 Recordes pessoais de treino</h4><div class="perfil-stats"><div class="card"><small>Maior distância em um treino</small><strong>${melhorKm.toFixed(2).replace('.',',')} km</strong></div><div class="card"><small>Melhor ritmo médio de um treino</small><strong>${a.length?treinoDuracao(Math.round(melhorRitmo))+' /km':'—'}</strong></div></div><h4>📈 Evolução mensal da distância</h4><div class="perfil-chart">${ultimos.map(([mes,dist])=>`<div class="perfil-bar"><span>${dist.toFixed(1).replace('.',',')} km</span><div class="perfil-bar-track"><div style="height:${Math.max(3,dist/maximo*100)}%"></div></div><small>${esc(mes.slice(5)+'/'+mes.slice(0,4))}</small></div>`).join('')||'<p class="muted">Os gráficos aparecerão após o primeiro treino online válido.</p>'}</div><h4>🎖️ Medalhas digitais de treino</h4><div class="perfil-medals">${medals.map(m=>`<article class="card ${m.ok?'':'perfil-medal-locked'}"><div class="perfil-medal-icon">${m.ico}</div><strong>${esc(m.titulo)}</strong><small>${esc(m.desc)}</small><span>${m.ok?'Conquistada':'Bloqueada'}</span></article>`).join('')}</div><p class="muted">Medalhas virtuais automáticas baseadas em treinos GPS válidos registrados online. Não equivalem a premiação oficial nem a resultados homologados de provas. Treinos removidos pela administração não são contabilizados.</p><h4>📋 Últimos treinos</h4><div class="tablewrap"><table><thead><tr><th>Data</th><th>Distância</th><th>Tempo</th><th>Ritmo</th><th>Pontos</th></tr></thead><tbody>${a.slice(0,15).map(t=>`<tr><td>${esc(new Date(t.iniciado_em).toLocaleDateString('pt-BR'))}</td><td>${t.km.toFixed(2).replace('.',',')} km</td><td>${treinoDuracao(t.seg)}</td><td>${treinoDuracao(Math.round(t.seg/t.km))} /km</td><td>${t.pts.toFixed(2).replace('.',',')}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum treino online válido encontrado.</td></tr>'}</tbody></table></div></div>`;
}
function perfil(){return `${onlinePanel()}${heading('Cadastro exclusivo para o ranking dos servidores do IFAP','O pré-cadastro do ranking oficial de 2027 está temporariamente bloqueado')}<div class="two"><div class="panel"><h3>🏃 Pré-cadastro aberto para servidores do IFAP</h3><p class="muted">Preencha seu perfil. Com a conta online conectada, os dados são salvos automaticamente no banco ao concluir o formulário. Se você preencher antes de entrar, o sistema tentará sincronizar após o login.</p><form id="profileForm"><div class="formgrid"><div class="full"><label>Nome de exibição</label><input name="nome" required maxlength="90" value="${esc(profile?.nome||'')}"></div><div><label>Município</label><select name="cidade">${['Macapá','Santana','Oiapoque','Porto Grande','Laranjal do Jari','Tartarugalzinho','Pedra Branca do Amapari','Mazagão','Calçoene','Amapá','Ferreira Gomes','Itaubal','Cutias','Pracuúba','Serra do Navio','Vitória do Jari'].map(v=>`<option ${profile?.cidade===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Categoria</label><select name="sexo">${['Masculino','Feminino','PcD'].map(v=>`<option ${profile?.sexo===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Modalidade do corredor</label><select name="nivel"><option value="Amador" ${(!profile?.nivel||profile.nivel==='Amador')?'selected':''}>Corredor amador</option><option value="Elite" ${profile?.nivel==='Elite'?'selected':''}>Corredor de elite</option></select></div><div><label>Faixa etária</label><select name="faixa">${['Até 17','18–29','30–39','40–49','50–59','60–69','70+'].map(v=>`<option ${profile?.faixa===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Classe esportiva PcD (se aplicável)</label><input name="classe" value="${esc(profile?.classe||'')}" placeholder="Definir após homologação"></div></div><button class="btn dark">${profile?'Atualizar pré-cadastro IFAP':'Concluir pré-cadastro IFAP'}</button></form></div><div class="panel" style="display:none"><h3>⏱️ Resultados oficiais • 2027</h3><p class="muted">${!profile?'Primeiro, conclua o pré-cadastro.':!seasonIsOpen()?'Envio disponível a partir de 1º de janeiro de 2027.':'Envie apenas resultados de provas realizadas em 2027.'}</p><form id="resultForm"><fieldset ${!seasonIsOpen()?'disabled':''} style="border:0;padding:0;margin:0"><div class="formgrid"><div class="full"><label>Nome oficial da corrida (será exibido na medalha digital)</label><input name="prova" required minlength="3" maxlength="120" placeholder="Ex.: 3ª Corrida do IFAP"></div><div><label>Data da prova</label><input type="date" name="data" min="2027-01-01" max="2027-12-31" required ${!seasonIsOpen()?'disabled':''}></div><div><label>Distância</label><select name="dist">${['5 km'].map(v=>`<option>${v}</option>`).join('')}</select></div><div><label>Tempo oficial (hh:mm:ss)</label><input name="tempo" required pattern="[0-9]{1,2}:[0-5][0-9]:[0-5][0-9]" placeholder="00:25:30"></div><div><label>Número de peito</label><input name="peito" maxlength="20" required></div><div><label>Colocação geral oficial</label><input type="number" name="colocacao" min="1" max="100000" step="1" required placeholder="Ex.: 12"></div><div><label>Colocação na categoria (opcional)</label><input type="number" name="colocacaoCategoria" min="1" max="100000" step="1" placeholder="Ex.: 3"></div><div class="full"><label>Link público do resultado oficial (ou anexe PDF)</label><input type="url" name="url" pattern="https://.*" placeholder="https://site-da-cronometragem.com/resultado"></div><div class="full"><label>Ou anexar PDF oficial (até 5 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf"></div></div><button class="btn dark" ${!profile||!seasonIsOpen()?'disabled title="Disponível após o pré-cadastro e a abertura da temporada 2027"':''}>Enviar resultado de 2027 para revisão</button></fieldset></form></div></div>${medalhasCorridasIFAP()}${heading('Meus envios','Temporada 2027 • armazenados apenas neste navegador')}<div class="panel">${submissionTable(submissions)}</div><div class="notice">O pré-cadastro é local, sem conta online, autenticação ou sincronização entre dispositivos. Para receber cadastros reais será necessário configurar um banco de dados seguro. Não insira CPF, laudos, dados médicos ou documentos pessoais. O painel Admin é demonstrativo e não oferece controle de acesso.</div>`}
function submissionTable(list,admin=false){return `<div class="tablewrap"><table><thead><tr><th>Prova</th><th>Data</th><th>Tempo</th><th>Colocação</th><th>Comprovação</th><th>Status</th>${admin?'<th>Ação</th>':''}</tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(x.prova)}</strong><br>${esc(x.dist)}</td><td>${fmtdate(x.data)}</td><td>${esc(x.tempo)}</td><td>${esc(x.colocacao||'—')}</td><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Abrir ↗</a></td><td><span class="status ${x.status}">${x.status}</span></td>${admin?`<td><button onclick="review(${x.id},'aprovado')">Aprovar demo</button> <button onclick="review(${x.id},'rejeitado')">Rejeitar demo</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${admin?7:6}" class="empty">Nenhum resultado enviado.</td></tr>`}</tbody></table></div>`}

async function prepararComprovante(form){const dados=Object.fromEntries(new FormData(form));const file=form.querySelector('input[name="arquivo_pdf"]')?.files?.[0];delete dados.arquivo_pdf;if(!file&&!String(dados.url||'').trim()&&!(betaEditando&&betaMeus.some(r=>Number(r.id)===betaEditando&&r.comprovante_pdf)))throw Error('Informe o link oficial ou selecione um PDF.');if(file){if(file.type!=='application/pdf'||file.size>5*1024*1024||file.size<8)throw Error('Selecione um PDF válido de até 5 MB.');const body=new FormData();body.append('arquivo',file);const response=await fetch('/api/comprovante',{method:'POST',body,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw Error(result.erro||'Falha ao enviar PDF');dados.comprovante_pdf=result.comprovante_pdf}return dados}
function linkComprovante(r){const url=String(r.url||'');const pdf=String(r.comprovante_pdf||'');return `${/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">🔗 Link oficial</a> `:''}${/^[a-f0-9-]{36}$/.test(pdf)?`<a href="/api/comprovante?id=${encodeURIComponent(pdf)}" target="_blank" rel="noopener noreferrer">📄 Abrir PDF</a>`:''}`}
let betaAtletas=[],betaMeus=[],betaFila=[],betaErro='';
async function carregarBeta(){try{betaAtletas=(await onlineRequest('/api/beta2026')).atletas;betaErro='';if(onlineUser){betaMeus=(await onlineRequest('/api/beta2026?meus=1')).resultados;if(onlineUser.roles?.includes('admin'))betaFila=(await onlineRequest('/api/beta2026?fila=1')).resultados}}catch(e){betaErro=e.message}if(['beta2026','admin'].includes(state.page))render()}
async function analisarBeta(id,status){if(!confirm('Confirmar análise de 2026?'))return;try{await onlineRequest('/api/beta2026','PATCH',{id,status});await carregarBeta()}catch(e){alert(e.message)}}
let betaFiltros={tipo:'faixa',sexo:'Todos',faixa:'Todas',dist:'Todas',cidade:'Todos'};
function filtrarBeta(campo,valor){betaFiltros[campo]=valor;if(campo==='tipo'&&valor==='geral')betaFiltros.faixa='Todas';render()}
function filtroBetaSelect(campo,titulo,opcoes){return `<label>${titulo}<select onchange="filtrarBeta('${campo}',this.value)">${opcoes.map(v=>`<option value="${esc(v)}" ${betaFiltros[campo]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function rankingBetaFiltrado(){const porFaixa=betaFiltros.tipo==='faixa',porMunicipio=betaFiltros.tipo==='municipio';const grupos=new Map();for(const a of betaAtletas){const chave=[a.sexo,porFaixa?a.faixa:'GERAL',a.dist,a.classe||'',porMunicipio?a.cidade:'AMAPA'].join('|');if(!grupos.has(chave))grupos.set(chave,[]);grupos.get(chave).push(a)}const linhas=[];for(const [chave,grupo] of grupos){grupo.sort((a,b)=>Number(a.melhor_tempo)-Number(b.melhor_tempo)||String(a.nome).localeCompare(String(b.nome),'pt-BR'));grupo.forEach((a,i)=>{if((betaFiltros.sexo==='Todos'||a.sexo===betaFiltros.sexo)&&(betaFiltros.faixa==='Todas'||!porFaixa||a.faixa===betaFiltros.faixa)&&(betaFiltros.dist==='Todas'||a.dist===betaFiltros.dist)&&(betaFiltros.cidade==='Todos'||a.cidade===betaFiltros.cidade))linhas.push({...a,posicao:i+1,grupo:chave})})}return linhas.sort((a,b)=>(porMunicipio?a.cidade.localeCompare(b.cidade,'pt-BR'):0)||a.dist.localeCompare(b.dist,'pt-BR')||a.sexo.localeCompare(b.sexo,'pt-BR')||(porFaixa?a.faixa.localeCompare(b.faixa,'pt-BR'):0)||a.posicao-b.posicao)}

let betaEditando=null;
function editarBeta(id){const r=betaMeus.find(x=>Number(x.id)===Number(id)&&x.status==='rejeitado');if(!r)return;betaEditando=Number(id);render();const f=document.querySelector('#betaForm');if(!f)return;const campos={prova:r.prova,data:String(r.data).slice(0,10),localidade:r.localidade||'',dist:r.dist,tempo:time(Number(r.tempo_segundos)),colocacao:r.colocacao,url:r.url||''};for(const [nome,valor] of Object.entries(campos)){const campo=f.elements.namedItem(nome);if(campo)campo.value=valor}f.scrollIntoView({behavior:'smooth',block:'start'})}
function cancelarEdicaoBeta(){betaEditando=null;render()}
function beta2026(){return `${heading('🏅 Ranking Experimental 2026','Somente medalha digital e divulgação dos melhores corredores. Sem premiação física ou financeira.')}<div class="panel"><h3>Melhores resultados homologados de 2026</h3><p>Três rankings independentes: geral estadual, por faixa etária e geral por município. Todos consideram categoria e distância. Os resultados não contam para 2027.</p><div class="actions"><button class="btn ${betaFiltros.tipo==='geral'?'':'secondary'}" onclick="filtrarBeta('tipo','geral')">🏆 Ranking geral</button><button class="btn ${betaFiltros.tipo==='faixa'?'':'secondary'}" onclick="filtrarBeta('tipo','faixa')">🏅 Por faixa etária</button><button class="btn ${betaFiltros.tipo==='municipio'?'':'secondary'}" onclick="filtrarBeta('tipo','municipio')">📍 Geral por município</button></div><div class="filters">${filtroBetaSelect('sexo','Categoria',['Todos','Masculino','Feminino','PcD'])}${betaFiltros.tipo==='faixa'?filtroBetaSelect('faixa','Faixa etária',['Todas','Até 17','18–29','30–39','40–49','50–59','60–69','70+']):''}${filtroBetaSelect('dist','Distância',['Todas','5 km'])}${filtroBetaSelect('cidade','Município',['Todos','Amapá','Calçoene','Cutias','Ferreira Gomes','Itaubal','Laranjal do Jari','Macapá','Mazagão','Oiapoque','Pedra Branca do Amapari','Porto Grande','Pracuúba','Santana','Serra do Navio','Tartarugalzinho','Vitória do Jari'])}</div><p class="muted">Ranking geral: posição estadual por categoria e distância. Faixa etária: posição estadual por idade, categoria e distância. Geral por município: posição própria de cada município, sem divisão por idade. Filtrar município não altera as posições estaduais.</p><div class="tablewrap"><table><thead><tr><th>Pos.</th><th>Atleta</th><th>Município</th><th>Categoria</th><th>Faixa etária</th><th>Distância</th><th>Melhor tempo</th></tr></thead><tbody>${rankingBetaFiltrado().map(a=>`<tr><td><span class="place ${a.posicao<=5?'top':''}">${a.posicao}º</span></td><td><strong>${esc(a.nome)}</strong></td><td>${esc(a.cidade)}</td><td>${esc(a.sexo)}${a.classe?' • '+esc(a.classe):''}</td><td>${esc(a.faixa)}</td><td>${esc(a.dist)}</td><td><strong>${time(Number(a.melhor_tempo))}</strong></td></tr>`).join('')||'<tr><td colspan="7">Nenhum resultado homologado encontrado para estes filtros.</td></tr>'}</tbody></table></div>${betaErro?`<p class="notice">${esc(betaErro)}</p>`:''}<button class="btn secondary" onclick="carregarBeta()">Atualizar</button></div><div class="panel"><h3>${betaEditando?'✏️ Corrigir resultado rejeitado':'Cadastrar resultado oficial de 2026'}</h3><p class="muted">Entre na conta e salve seu perfil online antes de enviar. Cada resultado passa por homologação.</p>${!onlineUser||!onlineProfile?'<button class="btn" onclick="go(\'perfil\')">Entrar e concluir cadastro</button>':`<form id="betaForm" class="formgrid"><div class="full"><label>Nome oficial da corrida</label><input name="prova" required minlength="3" maxlength="120"></div><div><label>Data em 2026</label><input name="data" type="date" min="2026-01-01" max="2026-12-31" required></div><div class="full"><label>Localidade onde ocorreu a corrida</label><input name="localidade" maxlength="120" placeholder="Ex.: Macapá/AP — Marco Zero"></div><div><label>Distância</label><select name="dist"><option>5 km</option></select></div><div><label>Tempo oficial (hh:mm:ss)</label><input name="tempo" required pattern="[0-9]{1,2}:[0-5][0-9]:[0-5][0-9]" placeholder="00:25:30"></div><div><label>Colocação geral</label><input type="number" name="colocacao" min="1" required></div><div class="full"><label>Link HTTPS do resultado oficial (opcional se anexar PDF)</label><input type="url" name="url" placeholder="https://..."></div><div class="full"><label>Ou anexar PDF do resultado (até 5 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf"></div><button class="btn dark">Enviar para homologação</button></form>`}</div><div class="panel"><h3>🏅 Minhas medalhas digitais — 2026</h3><p>As medalhas digitais são liberadas somente após a homologação.</p>${betaMeus.map(r=>`<p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(r.status)} ${r.status==='aprovado'?`<button class="btn secondary" onclick="baixarMedalhaBeta(${Number(r.id)})">Baixar medalha</button>`:r.status==='rejeitado'?`<button class="btn secondary" onclick="editarBeta(${Number(r.id)})">✏️ Editar e reenviar</button>`:''}</p>`).join('')||'<p>Nenhum resultado enviado.</p>'}</div>`}
function baixarMedalhaBeta(id){
 const r=betaMeus.find(x=>Number(x.id)===Number(id)&&x.status==='aprovado');if(!r)return;
 const p=onlineProfile||{},a=betaAtletas.find(x=>Number(x.atleta_id)===Number(r.atleta_id));
 const nome=String(p.nome||a?.nome||'Atleta participante').trim(),prova=String(r.prova||'Corrida oficial').trim();
 const local=String(r.localidade||'Localidade não informada').trim();
 const distancia=String(r.dist||'—'),tempo=time(Number(r.tempo_segundos)),colocacao=Number(r.colocacao)>0?Number(r.colocacao)+'º':'—';
 const escSvg=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const texto=(x,y,v,tam=30,cor='#ffffff',peso=700,alinhamento='middle')=>`<text x="${x}" y="${y}" fill="${cor}" font-family="Arial,Helvetica,sans-serif" font-size="${tam}" font-weight="${peso}" text-anchor="${alinhamento}">${escSvg(v)}</text>`;
 const linhas=(v,max=35,limite=2)=>{const palavras=String(v).split(/\s+/);const out=[];let atual='';for(const palavra of palavras){if((atual+' '+palavra).trim().length>max&&atual){out.push(atual);atual=palavra}else atual=(atual+' '+palavra).trim()}if(atual)out.push(atual);if(out.length>limite){out.length=limite;out[limite-1]=out[limite-1].slice(0,max-1)+'…'}return out};
 const nomeLinhas=linhas(nome,31,2),provaLinhas=linhas(prova,35,2),localLinhas=linhas(local,37,2);
 const foto=String(p.foto_perfil||'');
 const fotoSvg=/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(foto)?`<image href="${foto}" x="170" y="575" width="150" height="150" preserveAspectRatio="xMidYMid slice" clip-path="url(#fotoMedalha)"/>`:`<circle cx="245" cy="650" r="75" fill="#0b5036"/><path d="M245 603a27 27 0 1 1 0 54a27 27 0 0 1 0-54 M192 710c5-57 101-57 106 0" fill="#d7bd64"/>`;
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200" role="img" aria-label="Medalha digital Ranking Amapá Running 2026">
 <defs><radialGradient id="verde"><stop stop-color="#116b49"/><stop offset=".7" stop-color="#07462f"/><stop offset="1" stop-color="#03291e"/></radialGradient><linearGradient id="ouro" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#fff6bc"/><stop offset=".24" stop-color="#c18b20"/><stop offset=".48" stop-color="#ffe486"/><stop offset=".77" stop-color="#a66c12"/><stop offset="1" stop-color="#fbe59a"/></linearGradient><clipPath id="fotoMedalha"><circle cx="245" cy="650" r="75"/></clipPath></defs>
 <rect width="1200" height="1200" fill="#061a13"/><circle cx="600" cy="600" r="578" fill="url(#ouro)"/><circle cx="600" cy="600" r="548" fill="url(#verde)" stroke="#fff0a4" stroke-width="8"/><circle cx="600" cy="600" r="528" fill="none" stroke="#2ef46d" stroke-width="6"/><circle cx="600" cy="600" r="510" fill="none" stroke="#b99539" stroke-width="3"/>
 <path d="M225 389L340 333L405 350L505 280L576 315L673 260L742 305L840 274L970 370" stroke="#24de68" stroke-width="8" fill="none" stroke-linejoin="round" opacity=".85"/>
 <g fill="#e7bf51" stroke="#ffedaa" stroke-width="1" opacity=".95">
 ${Array.from({length:8},(_,i)=>{const y=445+i*64;const x=120+i*9;return `<ellipse cx="${x+25}" cy="${y}" rx="17" ry="39" transform="rotate(-30 ${x+25} ${y})"/><ellipse cx="${1080-i*9-25}" cy="${y}" rx="17" ry="39" transform="rotate(30 ${1080-i*9-25} ${y})"/>`}).join('')}
 </g>
 <g opacity=".85"><path d="M435 540H765M515 540L540 507H660L685 540M560 507L575 485H625L640 507" fill="none" stroke="#d9ba60" stroke-width="5"/><path d="M593 485V457H607V485" fill="#f4d275"/><circle cx="600" cy="454" r="8" fill="#f7e39a"/></g>
 ${texto(600,154,'R A N K I N G',38,'#f4d477')}${texto(600,257,'AMAPÁ',112)}${texto(600,316,'R U N N I N G',48,'#f5d57c')}${texto(600,401,'2026',78,'#ffe58b')}${texto(600,448,'MEDALHA DIGITAL',39)}${texto(600,485,'EDIÇÃO EXPERIMENTAL',25,'#f8d980')}
 <path d="M420 534H780" stroke="#e2b64c" stroke-width="4"/><circle cx="600" cy="534" r="9" fill="#ffe08b"/>
 <rect x="128" y="560" width="944" height="194" rx="49" fill="url(#ouro)" stroke="#fff4c4" stroke-width="5"/>
 <circle cx="245" cy="650" r="87" fill="#e9b848" stroke="#fff6d5" stroke-width="6"/>${fotoSvg}<circle cx="245" cy="650" r="75" fill="none" stroke="#ffeab4" stroke-width="5"/>
 ${nomeLinhas.map((l,i)=>texto(360,632+i*42,l,nomeLinhas.length>1?33:39,'#103b2b',800,'start')).join('')}
 ${texto(360,722,'PARTICIPANTE • RESULTADO HOMOLOGADO',22,'#21523b',700,'start')}
 <rect x="165" y="774" width="870" height="303" rx="35" fill="#063524" stroke="#e8c35f" stroke-width="7"/>
 ${texto(600,816,'PROVA CADASTRADA',22,'#d6b85e')}
 ${provaLinhas.map((l,i)=>texto(600,856+i*34,l,provaLinhas.length>1?29:35,'#ffffff',800)).join('')}
 <path d="M208 924H992" stroke="#9b823d" stroke-width="2"/>
 ${texto(340,955,'DISTÂNCIA',22,'#e8c76e')}${texto(600,955,'TEMPO OFICIAL',22,'#e8c76e')}${texto(857,955,'COLOCAÇÃO',22,'#e8c76e')}
 ${texto(340,1002,distancia,40)}${texto(600,1002,tempo,40)}${texto(857,1002,colocacao,47,'#ffdf78')}
 <path d="M464 940V1020M733 940V1020" stroke="#927c39" stroke-width="2"/>
 ${texto(600,1047,'LOCALIDADE',19,'#e8c76e')}
 ${localLinhas.map((l,i)=>texto(600,1075+i*24,l,localLinhas.length>1?20:23,'#ffffff',600)).join('')}
 ${texto(600,1140,'AMAPÁ • MEIO DO MUNDO • 2026',22,'#f5d982')}
 </svg>`;
 const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='medalha-amapa-running-2026-'+id+'.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500)
}

function painelBetaAdmin(){if(!onlineUser?.roles?.includes('admin'))return '';return `<section class="panel review-panel"><div class="review-heading"><div><span class="tag">TEMPORADA EXPERIMENTAL</span><h3>🏅 Homologação de resultados — 2026</h3><p class="muted">Confira o resultado publicado pela organização da corrida antes de decidir. Somente resultados aprovados entram no ranking e geram medalhas digitais.</p></div><strong class="review-count">${betaFila.length} pendente(s)</strong></div>${betaFila.map(r=>`<article class="review-item"><div><strong>${esc(r.nome)}</strong><p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(String(r.data).slice(0,10))}</p><p>Tempo: ${time(Number(r.tempo_segundos))} • Colocação geral: ${Number(r.colocacao)}</p>${linkComprovante(r)}</div><div class="review-actions"><button class="btn dark" onclick="analisarBeta(${Number(r.id)},'aprovado')">✓ Homologar</button><button class="btn secondary" onclick="analisarBeta(${Number(r.id)},'rejeitado')">✕ Rejeitar</button></div></article>`).join('')||'<p class="muted">Nenhum resultado experimental aguardando homologação.</p>'}<button class="btn secondary" onclick="carregarBeta()">Atualizar fila de 2026</button></section>`}
