const treinoDuracao=seg=>{seg=Math.max(0,Math.floor(seg));return String(Math.floor(seg/3600)).padStart(2,'0')+':'+String(Math.floor(seg%3600/60)).padStart(2,'0')+':'+String(seg%60).padStart(2,'0')};
function treinoDistancia(a,b){const rad=Math.PI/180,lat=(b.latitude-a.latitude)*rad,lon=(b.longitude-a.longitude)*rad,x=Math.sin(lat/2)**2+Math.cos(a.latitude*rad)*Math.cos(b.latitude*rad)*Math.sin(lon/2)**2;return 12742000*Math.asin(Math.min(1,Math.sqrt(x)))}
const TREINO_BACKUP='amapa_treino_gps_v1';let treinoBackupTimer=null;
