function treinoRecuperar(){if(treinoAtivo||!navigator.geolocation)return;try{const v=JSON.parse(localStorage.getItem(TREINO_BACKUP)||'null');if(!v||v.versao!==1||!Number.isFinite(v.inicio)||Date.now()-v.inicio>86400000)return;if(!Number.isFinite(v.metros)||v.metros<0||v.metros>100000)return;treinoAtivo={...v,watch:null,timer:null,ultimo:null,pausaInicio:null,pausaTotal:(v.pausaTotal||0)+Math.max(0,Date.now()-(v.ultimoSinal||v.inicio)),ultimoSinal:null};treinoErro='Treino recuperado. O intervalo sem GPS foi excluído do tempo ativo; a distância desse intervalo não pode ser recuperada.';treinoReativarGPS();treinoAtivo.timer=setInterval(treinoAtualizarPainel,1000);treinoSalvarBackup();render()}catch(e){console.warn('Não foi possível recuperar treino',e)}}
function treinoVisibilidade(){const t=treinoAtivo;if(!t)return;if(document.hidden){treinoSalvarBackup();return}if(t.ultimoSinal&&Date.now()-t.ultimoSinal>30000){t.ultimo=null;treinoErro='O navegador pode suspender o GPS com a tela bloqueada. Trecho sem sinal não contabilizado.';treinoReativarGPS()}treinoAtualizarPainel()}
