function treinoPosicao(p){
 const t=treinoAtivo;if(!t||t.pausaInicio)return;
 const c=p.coords,agora=Date.now(),ts=Number(p.timestamp);
 t.ultimaPrecisao=c.accuracy;
 const avisar=msg=>{treinoErro=msg;const el=document.getElementById('treinoAviso');if(el)el.textContent=msg};
 if(!Number.isFinite(ts)||ts>agora+5000||agora-ts>15000||!Number.isFinite(c.accuracy)||c.accuracy>20||c.accuracy<0||!Number.isFinite(c.latitude)||Math.abs(c.latitude)>90||!Number.isFinite(c.longitude)||Math.abs(c.longitude)>180){
  t.descartados++;t.ultimo=null;avisar('Precisão GPS insuficiente ou posição desatualizada. Aguardando sinal confiável; trecho não contabilizado.');treinoAtualizarPainel();return;
 }
 const atual={latitude:c.latitude,longitude:c.longitude,timestamp:ts,accuracy:c.accuracy};
 if(!t.ultimo){t.ultimo=atual;t.ultimoSinal=agora;t.pontosValidos++;treinoErro='GPS confiável. Monitorando percurso.';treinoSalvarBackup();treinoAtualizarPainel();return}
 const seg=(ts-t.ultimo.timestamp)/1000;
 if(seg<=0){treinoAtualizarPainel();return}
 if(seg>15){t.ultimo=atual;t.descartados++;t.ultimoSinal=agora;avisar('Sinal GPS interrompido. Trecho sem sinal ignorado para evitar distância duplicada.');treinoSalvarBackup();treinoAtualizarPainel();return}
 const metros=treinoDistancia(t.ultimo,atual);
 const margem=Math.max(3,Math.min(10,(atual.accuracy+t.ultimo.accuracy)*.3));
 if(metros<=margem){t.ultimoSinal=agora;treinoAtualizarPainel();return}
 const velocidade=metros/seg;
 if(velocidade>7.5){t.descartados++;t.ultimo=null;avisar('Salto de GPS descartado. Aguardando novo ponto para retomar a medição.');treinoAtualizarPainel();return}
 t.metros+=metros;t.ultimo=atual;t.pontosValidos++;t.ultimoSinal=agora;treinoErro='GPS confiável. Distância calculada pelos pontos válidos.';treinoSalvarBackup();treinoAtualizarPainel();
}
function treinoPausar(){const t=treinoAtivo;if(!t||t.pausaInicio)return;t.pausaInicio=Date.now();t.ultimo=null;treinoErro='Treino pausado: distância não contabilizada.';treinoSalvarBackup();render()}
