function treinoFalha(e){treinoErro='GPS indisponível: '+(e?.message||'verifique a permissão de localização');if(treinoAtivo)treinoAtivo.ultimo=null;const x=document.getElementById('treinoAviso');if(x)x.textContent=treinoErro}
function treinoIniciar(){if(treinoAtivo)return;if(!navigator.geolocation||!window.isSecureContext){alert('O GPS exige HTTPS e um navegador com permissão de localização.');return}treinoErro='';treinoAtivo={inicio:Date.now(),metros:0,ultimo:null,ultimaPrecisao:null,watch:null,timer:null,descartados:0,pontosValidos:0,ultimoSinal:null};treinoAtivo.watch=navigator.geolocation.watchPosition(treinoPosicao,treinoFalha,{enableHighAccuracy:true,maximumAge:0,timeout:20000});treinoAtivo.timer=setInterval(treinoAtualizarPainel,1000);render()}
async function treinoParar(){if(!treinoAtivo)return;const t=treinoAtivo;treinoAtivo=null;navigator.geolocation.clearWatch(t.watch);clearInterval(t.timer);treinoSalvarBackup();const duracao=treinoDuracaoAtiva(t),metros=Math.round(t.metros);if(metros<10||duracao<30||t.pontosValidos<3||!t.ultimoSinal||Date.now()-t.ultimoSinal>90000){alert('Treino encerrado. Para entrar no ranking, registre ao menos 10 metros, 30 segundos e pelo menos 3 pontos de GPS válidos, com sinal recente.');render();return}if(!onlineUser||!onlineProfile){alert('Treino concluído e mantido no dispositivo para recuperação: '+(metros/1000).toFixed(2)+' km em '+treinoDuracao(duracao)+'. Entre na conta e complete o perfil antes de iniciar outro treino para salvar no ranking.');render();return}treinoSalvando=true;render();try{await onlineRequest('/api/treinos','POST',{distancia_m:metros,duracao_s:duracao,iniciado_em:new Date(t.inicio).toISOString()});await treinoCarregar();treinoLimparBackup();alert('Treino registrado no ranking de treinos!')}catch(e){alert('Treino encerrado, mas não foi salvo no ranking: '+e.message)}finally{treinoSalvando=false;render()}}
